class student_Type:
    def f_Calculate_Gpax(self, f_point_total, f_credit_total):
        MAX_GPAX = 4.0
        f_gpax = 0.0
        # check that credits were registered
        if f_credit_total > 0:
            f_gpax = f_point_total / f_credit_total
        # else no credit registered, keep GPAX at zero
        else:
            f_gpax = 0.0
        return min(f_gpax, MAX_GPAX)
